// Build a Google Calendar event payload that includes a Google Meet link
// and all students as guests. Google will email every guest automatically.
const b = $input.first().json.body ?? $input.first().json;

const courseTitle  = b.course_title  || 'Séance en ligne';
const date         = b.date;            // "2026-06-10"
const startTime    = b.start_time;      // "14:00"
const duration     = Number(b.duration_minutes) || 60;
const teacherEmail = b.teacher_email || null;
const students     = Array.isArray(b.students) ? b.students : [];

if (!date || !startTime) throw new Error('date and start_time are required (YYYY-MM-DD, HH:MM).');

// Format naive local wall-clock strings (Google applies the timeZone below)
const pad   = (n) => String(n).padStart(2, '0');
const naive = (d) => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:00`;

const start = new Date(`${date}T${startTime}:00`);
const end   = new Date(start.getTime() + duration * 60000);
const tz    = 'Africa/Casablanca';

const attendees = students.filter(s => s && s.email).map(s => ({ email: s.email }));
if (teacherEmail) attendees.push({ email: teacherEmail });

const event = {
  summary: `${courseTitle} — Séance en ligne`,
  description: `Séance en ligne CampusEye — ${courseTitle}. Rejoignez via le lien Google Meet.`,
  start: { dateTime: naive(start), timeZone: tz },
  end:   { dateTime: naive(end),   timeZone: tz },
  attendees,
  reminders: { useDefault: true },
  conferenceData: {
    createRequest: {
      requestId: `campuseye-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      conferenceSolutionKey: { type: 'hangoutsMeet' },
    },
  },
};

return [{ json: { event } }];
